 60→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 61→	logCtx := logging.WithComponent(ctx, "attach")
 62→
 63→	// Validate session ID format
 64→	if err := validation.ValidateSessionID(sessionID); err != nil {
 65→		return fmt.Errorf("invalid session ID: %w", err)
 66→	}
 67→
 68→	// Ensure we're in a git repo
 69→	repoRoot, err := paths.WorktreeRoot(ctx)
 70→	if err != nil {
 71→		return fmt.Errorf("not a git repository: %w", err)
 72→	}
 73→
 74→	// Check session isn't already tracked
 75→	store, err := session.NewStateStore(ctx)
 76→	if err != nil {
 77→		return fmt.Errorf("failed to open session store: %w", err)
 78→	}
 79→	existing, err := store.Load(ctx, sessionID)
 80→	if err != nil {
 81→		return fmt.Errorf("failed to check existing session: %w", err)
 82→	}
 83→	if existing != nil {
 84→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 85→	}
 86→
 87→	// Resolve agent and transcript path
 88→	ag, err := agent.Get(agentName)
 89→	if err != nil {
 90→		return fmt.Errorf("agent %q not available: %w", agentName, err)
 91→	}
 92→	agentType := ag.Type()
 93→
 94→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
 95→	if err != nil {
 96→		return fmt.Errorf("failed to resolve transcript path: %w", err)
 97→	}
 98→	// Agents use cwd-derived project directories, so the transcript may be stored under
 99→	// a different project directory if the session was started from a different working directory.
100→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
101→		if found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag); searchErr == nil {
102→			logging.Info(logCtx, "found transcript in alternative project directory", "path", found)
103→			transcriptPath = found
104→		} else {
105→			logging.Debug(logCtx, "fallback transcript search failed", "error", searchErr)
106→		}
107→	}
108→	if _, statErr := os.Stat(transcriptPath); statErr != nil {
109→		return fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
110→	}
111→
112→	// Read transcript data
113→	transcriptData, err := ag.ReadTranscript(transcriptPath)
114→	if err != nil {
115→		return fmt.Errorf("failed to read transcript: %w", err)
116→	}
117→
118→	// Extract modified files from transcript
119→	var modifiedFiles []string
120→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
121→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
122→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
123→		} else {
124→			modifiedFiles = files
125→		}
126→	}
127→
128→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
129→	changes, err := DetectFileChanges(ctx, nil)
130→	if err != nil {
131→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
132→	}
133→
134→	// Filter and normalize paths
135→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
136→	var relNewFiles, relDeletedFiles []string
137→	if changes != nil {
138→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
139→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
140→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
141→	}
142→
143→	// Filter to uncommitted files only
144→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
145→
146→	if err := strategy.EnsureSetup(ctx); err != nil {
147→		return fmt.Errorf("failed to set up strategy: %w", err)
148→	}
149→
150→	// Create session metadata directory and copy transcript
151→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
152→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
153→	if err != nil {
154→		return fmt.Errorf("failed to resolve session directory path: %w", err)
155→	}
156→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
157→		return fmt.Errorf("failed to create session directory: %w", err)
158→	}
159→	// Normalize Gemini transcripts so the content field is a plain string
160→	// (Gemini user messages use [{"text":"..."}] arrays, which the UI can't render).
161→	storedTranscript := transcriptData
162→	if agentType == agent.AgentTypeGemini {
163→		if normalized, normErr := normalizeGeminiTranscript(transcriptData); normErr == nil {
164→			storedTranscript = normalized
165→		} else {
166→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
167→		}
168→	}
169→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
170→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
171→		return fmt.Errorf("failed to write transcript: %w", err)
172→	}
173→
174→	// Get git author
175→	author, err := GetGitAuthor(ctx)
176→	if err != nil {
177→		return fmt.Errorf("failed to get git author: %w", err)
178→	}
179→
180→	// Extract first prompt from transcript for the commit message
181→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
182→	commitMessage := generateCommitMessage(firstPrompt, agentType)
183→
184→	// Write prompt.txt so SaveStep includes it on the shadow branch
185→	// and CondenseSession can read it for the checkpoint metadata.
186→	if firstPrompt != "" {
187→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
188→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
189→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
190→		}
191→	}
192→
193→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
194→	strat := GetStrategy(ctx)
195→	if err := strat.InitializeSession(ctx, sessionID, agentType, transcriptPath, firstPrompt, ""); err != nil {
196→		return fmt.Errorf("failed to initialize session: %w", err)
197→	}
198→
199→	// Enrich session state with transcript-derived metadata
200→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, transcriptPath); err != nil {
201→		return err
202→	}
203→
204→	// Build step context and save checkpoint
205→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
206→
207→	stepCtx := strategy.StepContext{
208→		SessionID:      sessionID,
209→		ModifiedFiles:  relModifiedFiles,
210→		NewFiles:       relNewFiles,
211→		DeletedFiles:   relDeletedFiles,
212→		MetadataDir:    sessionDir,
213→		MetadataDirAbs: sessionDirAbs,
214→		CommitMessage:  commitMessage,
215→		TranscriptPath: transcriptPath,
216→		AuthorName:     author.Name,
217→		AuthorEmail:    author.Email,
218→		AgentType:      agentType,
219→	}
220→
221→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
222→		return fmt.Errorf("failed to save checkpoint: %w", err)
223→	}
224→
225→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
226→
227→	// Print confirmation
228→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
229→	if totalChanges > 0 {
230→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
231→	} else {
232→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
233→	}
234→	if condenseErr != nil {
235→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
236→	}
237→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
238→
239→	// Offer to amend the last commit with the checkpoint trailer
240→	if checkpointIDStr != "" {
241→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
242→			logging.Warn(logCtx, "failed to amend commit", "error", err)
243→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
244→		}
245→	}
246→
247→	return nil
248→}
