250→// enrichSessionState loads the session state after initialization and populates it with
251→// transcript-derived metadata (token usage, turn count, model name, duration).
252→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string) error {
253→	state, err := strategy.LoadSessionState(ctx, sessionID)
254→	if err != nil {
255→		return fmt.Errorf("failed to load session state: %w", err)
256→	}
257→	if state == nil {
258→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
259→	}
260→	state.CLIVersion = versioninfo.Version
261→	state.TranscriptPath = transcriptPath
262→
263→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
264→		state.TokenUsage = usage
265→	}
266→	if turns := countUserTurns(transcriptData); turns > 0 {
267→		state.SessionTurnCount = turns
268→	}
269→	if model := extractModelFromTranscript(transcriptData); model != "" {
270→		state.ModelName = model
271→	}
272→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
273→		state.SessionDurationMs = dur
274→	}
275→
276→	if err := strategy.SaveSessionState(ctx, state); err != nil {
277→		return fmt.Errorf("failed to save session state: %w", err)
278→	}
279→	return nil
280→}
