475→// extractModelFromTranscript extracts the model name from a JSONL transcript.
476→// Best-effort: returns empty string if the transcript format doesn't include model info
477→// (e.g., Gemini stores model info in hook events, not the transcript).
478→func extractModelFromTranscript(data []byte) string {
479→	lines, err := transcript.ParseFromBytes(data)
480→	if err != nil {
481→		return ""
482→	}
483→
484→	for _, line := range lines {
485→		if line.Type != transcript.TypeAssistant {
486→			continue
487→		}
488→		var msg struct {
489→			Model string `json:"model"`
490→		}
491→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
492→			return msg.Model
493→		}
494→	}
495→	return ""
496→}
