 20→// HookNames returns the hook verbs Gemini CLI supports.
 21→// These become subcommands: entire hooks gemini <verb>
 22→func (g *GeminiCLIAgent) HookNames() []string {
 23→	return []string{
 24→		HookNameSessionStart,
 25→		HookNameSessionEnd,
 26→		HookNameBeforeAgent,
 27→		HookNameAfterAgent,
 28→		HookNameBeforeModel,
 29→		HookNameAfterModel,
 30→		HookNameBeforeToolSelection,
 31→		HookNameBeforeTool,
 32→		HookNameAfterTool,
 33→		HookNamePreCompress,
 34→		HookNameNotification,
 35→	}
 36→}
 37→
 38→// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
 39→// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
 40→func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 41→	switch hookName {
 42→	case HookNameSessionStart:
 43→		return g.parseSessionStart(stdin)
 44→	case HookNameBeforeAgent:
 45→		return g.parseTurnStart(stdin)
 46→	case HookNameAfterAgent:
 47→		return g.parseTurnEnd(stdin)
 48→	case HookNameSessionEnd:
 49→		return g.parseSessionEnd(stdin)
 50→	case HookNamePreCompress:
 51→		return g.parseCompaction(stdin)
 52→	case HookNameBeforeModel:
 53→		return g.parseBeforeModel(stdin)
 54→	case HookNameBeforeTool, HookNameAfterTool,
 55→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 56→		// Acknowledged hooks with no lifecycle action
 57→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 58→	default:
 59→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 60→	}
 61→}
