 72→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
 73→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
 74→	var transcript struct {
 75→		Messages []geminiMessageWithTokens `json:"messages"`
 76→	}
 77→
 78→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
 79→		return &agent.TokenUsage{}, fmt.Errorf("failed to parse transcript for token usage: %w", err)
 80→	}
 81→
 82→	usage := &agent.TokenUsage{}
 83→
 84→	for i, msg := range transcript.Messages {
 85→		// Skip messages before startMessageIndex
 86→		if i < fromOffset {
 87→			continue
 88→		}
 89→
 90→		// Only count tokens from gemini (assistant) messages
 91→		if msg.Type != MessageTypeGemini {
 92→			continue
 93→		}
 94→
 95→		if msg.Tokens == nil {
 96→			continue
 97→		}
 98→
 99→		usage.APICallCount++
100→		usage.InputTokens += msg.Tokens.Input
101→		usage.OutputTokens += msg.Tokens.Output
102→		usage.CacheReadTokens += msg.Tokens.Cached
103→	}
104→
105→	return usage, nil
106→}
