103→// toolResultBlock represents a tool_result in a user message
104→type toolResultBlock struct {
105→	Type      string `json:"type"`
106→	ToolUseID string `json:"tool_use_id"`
107→}
108→
109→// userMessageWithToolResults represents a user message that may contain tool results
110→type userMessageWithToolResults struct {
111→	Content []toolResultBlock `json:"content"`
112→}
