114→// FindCheckpointUUID finds the UUID of the message containing the tool_result
115→// for the given tool_use_id. This is used to find the checkpoint point for
116→// transcript truncation when rewinding to a task.
117→// Returns the UUID and true if found, empty string and false otherwise.
118→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
119→	for _, line := range transcript {
120→		if line.Type != transcriptTypeUser {
121→			continue
122→		}
123→
124→		var msg userMessageWithToolResults
125→		if err := json.Unmarshal(line.Message, &msg); err != nil {
126→			continue
127→		}
128→
129→		for _, block := range msg.Content {
130→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
131→				return line.UUID, true
132→			}
133→		}
134→	}
135→	return "", false
136→}
