182→// TranscriptPosition contains the position information for a transcript file.
183→type TranscriptPosition struct {
184→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
185→	LineCount int    // Total number of lines
186→}
187→
188→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
189→// Returns empty position if file doesn't exist or is empty.
190→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
191→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
192→	if path == "" {
193→		return TranscriptPosition{}, nil
194→	}
195→
196→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
197→	if err != nil {
198→		if os.IsNotExist(err) {
199→			return TranscriptPosition{}, nil
200→		}
201→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
202→	}
203→	defer func() { _ = file.Close() }()
204→
205→	var pos TranscriptPosition
206→	reader := bufio.NewReader(file)
207→
208→	for {
209→		lineBytes, err := reader.ReadBytes('\n')
210→		if err != nil && err != io.EOF {
211→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
212→		}
213→
214→		if len(lineBytes) == 0 {
215→			if err == io.EOF {
216→				break
217→			}
218→			continue
219→		}
220→
221→		pos.LineCount++
222→
223→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
224→		var line transcriptLine
225→		if err := json.Unmarshal(lineBytes, &line); err == nil {
226→			if line.UUID != "" {
227→				pos.LastUUID = line.UUID
228→			}
229→		}
230→
231→		if err == io.EOF {
232→			break
233→		}
234→	}
235→
236→	return pos, nil
237→}
